PREFIX gvp: <http://vocab.getty.edu/ontology#>
PREFIX xl: <http://www.w3.org/2008/05/skos-xl#>
SELECT DISTINCT ?term WHERE {
  ?item gvp:broaderExtended <http://vocab.getty.edu/aat/300000885> ;
        xl:prefLabel/xl:literalForm ?term .
  FILTER(langMatches(lang(?term), "zh"))
}

